```csharp
using System;
using System.IO;

namespace BotFolderHelper
{
    public static class Bot08_09
    {
        // Ruta absoluta basada en el perfil del usuario actual
        private static readonly string BasePath = Path.Combine(
            Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),
            "bot-08-09");

        /// <summary>
        /// Garantiza que la carpeta exista; si no, la crea con los permisos por defecto.
        /// </summary>
        public static void EnsureExists()
        {
            try
            {
                Directory.CreateDirectory(BasePath); // No lanza si ya existe
            }
            catch (Exception ex)
            {
                Console.Error.WriteLine($"Error al crear la carpeta: {ex.Message}");
                throw;
            }
        }

        /// <summary>
        /// Lista los archivos de la carpeta de forma segura.
        /// </summary>
        public static void ListFiles()
        {
            EnsureExists();

            try
            {
                // Enumeración perezosa: evita cargar todos los nombres en memoria de golpe
                var files = Directory.EnumerateFiles(BasePath);
                bool any = false;

                foreach (var filePath in files)
                {
                    any = true;
                    var info = new FileInfo(filePath);
                    double sizeKb = info.Length / 1024.0;
                    Console.WriteLine(
                        $"- {info.Name} ({sizeKb:F2} KB) – Modificado: {info.LastWriteTime}");
                }

                if (!any)
                    Console.WriteLine("No hay archivos en la carpeta.");
            }
            catch (UnauthorizedAccessException)
            {
                Console.Error.WriteLine("Permiso denegado al intentar leer la carpeta.");
            }
            catch (DirectoryNotFoundException)
            {
                Console.Error.WriteLine("La carpeta no se encontró.");
            }
            catch (Exception ex)
            {
                Console.Error.WriteLine($"Error inesperado: {ex.Message}");
            }
        }

        /// <summary>
        /// Devuelve la ruta completa de la carpeta.
        /// </summary>
        public static string GetPath() => BasePath;
    }
}
```

